#include "Vdevice.h"
#include <winioctl.h>
#include <vjoyinterface.h>
#include <iostream>
#include <cstring>
using namespace bench;
Vdevice::Device_Config joystick(){using namespace Vdevice;Device_Config c;std::vector<uint8_t> report={5,1,9,4,0xa1,1,0x15,0,0x26,0xff,0x7f,9,0x30,9,0x31,0x75,16,0x95,2,0x81,2,5,9,0x19,1,0x29,32,0x15,0,0x25,1,0x75,1,0x95,32,0x81,2,0xc0};c.descriptors={{Descriptor_Kind::Standard,0,0,0,{18,1,0,2,0,0,0,64,0xff,0xff,0x54,0xb7,0,1,0,0,0,1}},{Descriptor_Kind::Standard,0,0,0,{9,2,34,0,1,1,0,0x80,50,9,4,0,0,1,3,0,0,0,9,0x21,0x11,1,0,1,0x22,uint8_t(report.size()),0,7,5,0x81,3,8,0,1}},{Descriptor_Kind::Report,0,0,0,report}};return c;}
int wmain(int argc,wchar_t** argv){fs::path out;try{if(argc!=4)return 2;guard();auto cfg=load(argv[1]);out=argv[2];require(!fs::exists(out),"Existing output");fs::create_directories(out);auto backend=cfg.at("backend").get<std::string>();require(backend=="vdevice"||backend=="vjoy","Unknown joystick backend");unsigned count=cfg.at("samples").get<unsigned>(),warm=cfg.at("warmup").get<unsigned>();require(count&&count+warm<30000,"Bounded joystick sequence");Vdevice::Device device;HMODULE dll=nullptr;decltype(&AcquireVJD) acquire=nullptr;decltype(&RelinquishVJD) release=nullptr;decltype(&UpdateVJD) update=nullptr;LONG minimum=0,maximum=32767;bool owned=false;
 struct Cleanup {HMODULE& dll;decltype(&RelinquishVJD)& release;bool& owned;~Cleanup(){if(owned)release(1);if(dll)FreeLibrary(dll);}}cleanup{dll,release,owned};
 if(backend=="vdevice"){device=Vdevice::Create_Device(joystick());require(bool(device),device.message.c_str());}
 else{dll=LoadLibraryW(L"C:\\TitanCSABenchmarkLab\\bin\\vJoyInterface.dll");require(dll!=nullptr,"Load pinned vJoy SDK");acquire=reinterpret_cast<decltype(acquire)>(GetProcAddress(dll,"AcquireVJD"));release=reinterpret_cast<decltype(release)>(GetProcAddress(dll,"RelinquishVJD"));update=reinterpret_cast<decltype(update)>(GetProcAddress(dll,"UpdateVJD"));auto getMin=reinterpret_cast<decltype(&GetVJDAxisMin)>(GetProcAddress(dll,"GetVJDAxisMin"));auto getMax=reinterpret_cast<decltype(&GetVJDAxisMax)>(GetProcAddress(dll,"GetVJDAxisMax"));require(acquire&&release&&update&&getMin&&getMax,"vJoy exports");require(acquire(1)!=FALSE,"Acquire vJoy device 1");owned=true;require(getMin(1,0x30,&minimum)&&getMax(1,0x30,&maximum)&&maximum>minimum,"vJoy axis range");}
 cfg["axis_min"]=minimum;cfg["axis_max"]=maximum;cfg["qpc_frequency"]=frequency();cfg["measurement"]="SDK update entry to independent WinMM joystick state visibility; closed loop";save(out/"joystick-run.json",cfg);if(cfg.value("collect_stack",false))require(waitfile(out/"stack-captured.json",60000),"Joystick PnP capture");
 auto name=L"Local\\TitanCSAJoy-"+std::to_wstring(GetCurrentProcessId())+L"-"+std::to_wstring(GetTickCount64());Handle mapping(CreateFileMappingW(INVALID_HANDLE_VALUE,nullptr,PAGE_READWRITE,0,sizeof(XInputChannel),name.c_str()));require(mapping.value!=nullptr,"Joystick mapping");auto* channel=static_cast<XInputChannel*>(MapViewOfFile(mapping.value,FILE_MAP_ALL_ACCESS,0,0,sizeof(XInputChannel)));require(channel!=nullptr,"Joystick map");ZeroMemory(channel,sizeof(*channel));Handle ack(CreateEventW(nullptr,FALSE,FALSE,(name+L"-ack").c_str()));require(ack.value!=nullptr,"Joystick event");std::wstring receiver=argv[3],cmd=L"\""+receiver+L"\" \""+out.wstring()+L"\" \""+name+L"\"";STARTUPINFOW si{};si.cb=sizeof(si);PROCESS_INFORMATION pi{};require(CreateProcessW(receiver.c_str(),cmd.data(),nullptr,nullptr,FALSE,CREATE_NO_WINDOW,nullptr,nullptr,&si,&pi)!=FALSE,"Start independent WinMM receiver");Handle process(pi.hProcess),thread(pi.hThread);struct Stop{XInputChannel* c;HANDLE p;~Stop(){InterlockedExchange(&c->stop,1);if(WaitForSingleObject(p,10000)!=WAIT_OBJECT_0)TerminateProcess(p,1);UnmapViewOfFile(c);}}stop{channel,process.value};auto end=GetTickCount64()+30000;while(!channel->ready&&GetTickCount64()<end)Sleep(10);require(channel->ready!=0,"WinMM receiver readiness");std::vector<std::array<int64_t,3>> rows;
 for(unsigned n=1;n<=count+warm;++n){auto x=minimum+LONG((n%200+1)*(maximum-minimum)/256),y=maximum-(x-minimum);uint32_t buttons=1u<<(n%8);auto start=qpc();channel->sent=start;InterlockedExchange(&channel->expected,LONG(n));if(backend=="vdevice"){std::vector<uint8_t> report(8);uint16_t a=uint16_t(x),b=uint16_t(y);std::memcpy(report.data(),&a,2);std::memcpy(report.data()+2,&b,2);std::memcpy(report.data()+4,&buttons,4);auto r=Vdevice::Send_Input(device,0x81,report);require(bool(r),r.message.c_str());}else{JOYSTICK_POSITION p{};p.bDevice=1;p.wAxisX=x;p.wAxisY=y;p.lButtons=LONG(buttons);p.bHats=p.bHatsEx1=p.bHatsEx2=p.bHatsEx3=0xffffffffu;require(update(1,&p)!=FALSE,"vJoy UpdateVJD");}auto returned=qpc();require(WaitForSingleObject(ack.value,5000)==WAIT_OBJECT_0&&channel->ack==LONG(n),"WinMM observation deadline");rows.push_back({n,start,returned});}
 InterlockedExchange(&channel->stop,1);require(WaitForSingleObject(process.value,10000)==WAIT_OBJECT_0,"WinMM receiver exit");DWORD code=1;require(GetExitCodeProcess(process.value,&code)&&code==0,"WinMM receiver success");std::ofstream f(out/"joystick-submission.csv");f<<"sequence,submit_qpc,return_qpc\n";for(auto r:rows)f<<r[0]<<','<<r[1]<<','<<r[2]<<'\n';f.close();save(out/"joystick-done.json",{{"status","completed"},{"resources",resources()}});return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';if(!out.empty()&&fs::exists(out))save(out/"joystick-error.json",{{"error",e.what()}});return 1;}}
